    (6283, 'Zona zoster oftalmica', 'zona zoster oftalmica', ARRAY['Zona zoster oftalmica', 'herpes zoster oftalmic', 'zona oftalmica', 'keratita zosteriana', 'herpes zoster ophthalmicus', 'ophthalmic zoster', 'ophthalmic herpes zoster', 'zona zoster a nervului oftalmic', 'zona zoster oculara', 'shingles of the eye']::text[], ARRAY['zona zoster oftalmica', 'herpes zoster oftalmic', 'zona oftalmica', 'keratita zosteriana', 'herpes zoster ophthalmicus', 'ophthalmic zoster', 'ophthalmic herpes zoster', 'zona zoster a nervului oftalmic', 'zona zoster oculara', 'shingles of the eye']::text[])
), missing AS (
    SELECT source.*,
           (SELECT COALESCE(MAX(sort_order) + 1, 0) FROM medical_conditions)
               + ROW_NUMBER() OVER (ORDER BY ordinal) - 1 AS next_order
    FROM source
    WHERE NOT EXISTS (
        SELECT 1 FROM medical_conditions c WHERE c.normalized_name = source.normalized_name
    )
), inserted AS (
    INSERT INTO medical_conditions(name, normalized_name, sort_order)
    SELECT name, normalized_name, next_order::integer FROM missing ORDER BY ordinal
    ON CONFLICT (normalized_name) DO NOTHING
    RETURNING condition_id, normalized_name
)
INSERT INTO medical_condition_terms(condition_id, position, term, normalized_term)
SELECT inserted.condition_id, (t.position - 1)::integer, t.term, t.normalized_term
FROM inserted JOIN source USING (normalized_name)
CROSS JOIN LATERAL unnest(source.terms, source.normalized_terms)
    WITH ORDINALITY AS t(term, normalized_term, position);
